 290| static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
 291| {
 292|     size_t got = 0;
 293| 
 294|     while (got < len) {
 295|         int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
 296| 
 297|         if (ret > 0) {
 298|             got += (size_t)ret;
 299|         } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
 300|             return -ECONNRESET;
 301|         } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
 302|             /* Distinguish SO_RCVTIMEO timeout from real I/O errors.
 303|              * When the socket recv timeout fires, recv() returns -1
 304|              * with errno EAGAIN/EWOULDBLOCK, and mbedtls maps that
 305|              * to MBEDTLS_ERR_NET_RECV_FAILED (-0x004C).  Return a
 306|              * distinct code so callers can treat timeout as normal
 307|              * end-of-stream without masking real connection failures. */
 308|             if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
 309|                                    || errno == ETIMEDOUT)) {
 310|                 return -ETIMEDOUT;
 311|             }
 312|             return -EIO;
 313|         }
