static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
{
    size_t got = 0;
    int want_read = 0;

    while (got < len) {
        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);

        if (ret > 0) {
            got += (size_t)ret;
            want_read = 0;
        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
            return -ECONNRESET;
        } else if (ret == MBEDTLS_ERR_SSL_WANT_READ) {
            /* 2026-08-15 修复（上板 T3 卡死根因）：阻塞 socket + SO_RCVTIMEO
             * 超时后 recv() 返回 -1/EAGAIN，mbedtls 映射为 WANT_READ（并非
             * 旧注释声称的 -0x004C）。原实现把 WANT_READ 当"继续读"空转，
             * 永不返回超时 → recv_wait_event 无限等待无日志。阻塞 socket 下
             * 每次 WANT_READ 都代表 SO_RCVTIMEO(10s) 无数据，连续 3 次
             * （≈30s 无数据）判超时返回。 */
            if (++want_read >= 3) {
                return -ETIMEDOUT;
            }
        } else {
            /* 真实 I/O 错误：区分超时（-0x004C + EAGAIN）与其他错误。 */
            if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
                                   || errno == ETIMEDOUT)) {
                return -ETIMEDOUT;
            }
            return -EIO;
        }
    }

    return 0;
}

