class Ctx:
    def __init__(self, stream, first_chunk=None):
        self.pend = bytearray()      # ctx->pend
        self.stream = bytearray(stream)  # 模拟 TLS 读缓冲
        self.first_chunk = first_chunk

    def ssl_read(self, n):
        """模拟 mbedtls_ssl_read：分块返回以模拟多次 TLS read。
        场景A（旧）：第一块恰好 101 头，之后 64B/块。
        场景B（新，大响应头）：第一块 1023B（无 \r\n\r\n，模拟 resp[1024]
