            # 用 first_chunk 作为第一块
            if self.first_chunk:
                take = min(n, self.first_chunk)
                self.first_chunk = 0
            else:
                take = min(n, 64)
        else:
            take = min(n, 64)
        out = bytes(self.stream[:take])
        del self.stream[:take]
        return out

